import{_ as a,c as r,o as t,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Redis Adapters: Cache Boundaries and Shared Limits — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/redis-adapters.md","filePath":"practice/node-js/redis-adapters.md"}'),s={name:"practice/node-js/redis-adapters.md"};function i(o,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="redis-adapters-cache-boundaries-and-shared-limits-—-practice" tabindex="-1">Redis Adapters: Cache Boundaries and Shared Limits — practice <a class="header-anchor" href="#redis-adapters-cache-boundaries-and-shared-limits-—-practice" aria-label="Permalink to “Redis Adapters: Cache Boundaries and Shared Limits — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/redis-adapters.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="practice-and-acceptance" tabindex="-1"><span class="hub-section-number">1 </span>Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “1 Practice and acceptance”">​</a></h2><p>Run only against an authorized isolated Redis instance with a bounded memory policy, no public listener and separate test credentials/namespace. Do not flush a shared server. Create two independent clients/adapters to represent two app replicas and close both even on failure.</p><p><strong>Acceptance:</strong> many concurrent calls through both clients allow exactly ten total requests for one subject, deny the rest, return positive bounded TTL and reset after expiry. Different tenants/users are independent; the same subject maps to one key. Verify malformed counter/type handling and expiry repair in a fresh namespace. Stop the server during calls: operation returns503 under policy, connection errors are handled, command/offline queues remain bounded and shutdown terminates. Do not equate a client timeout with rollback of a consumed slot.</p><p>For cache-aside, test valid-hit/no-source-read, malformed JSON, oversized/old-version/wrong-tenant/wrong-ID entries, read outage, fill outage, source rejection and invalid source shape. Corrupt/optional-cache failures fall back once per coalesced key; eight distinct blocked reads consume the whole budget and the ninth rejects without querying the source. Release/fail a read and prove capacity is reclaimed. Demonstrate stale-fill-after-invalidation and explain why TTL permits bounded staleness rather than strong consistency. Retain actual server/client versions and observed multi-client results. A port-based fake can test control flow but cannot prove Redis Lua atomicity, TTL or failover behavior. Learner execution remains required.</p><p>References checked2026-10-21: <a href="https://github.com/redis/node-redis/releases/tag/redis@6.3.0" target="_blank" rel="noreferrer">node-redis6.3 release</a>, <a href="https://github.com/redis/node-redis/blob/master/docs/client-configuration.md" target="_blank" rel="noreferrer">client configuration</a>, <a href="https://redis.io/docs/latest/develop/clients/nodejs/connect/" target="_blank" rel="noreferrer">connection lifetime</a>, <a href="https://redis.io/docs/latest/develop/programmability/eval-intro/" target="_blank" rel="noreferrer">Redis Lua execution</a>, <a href="https://redis.io/docs/latest/commands/incr/" target="_blank" rel="noreferrer">INCR counter/limit patterns</a>, <a href="https://redis.io/docs/latest/commands/expire/" target="_blank" rel="noreferrer">expiry semantics</a>. Some general Redis client guides show older commandOptions/quit APIs; the primary snippets use the installed6.3 declarations and require retesting on a version change.</p>',8)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
